function () {
  const s = inpLotStatus.selectedOptionValue || "All";
  switch (s) {
    case "New":
      return ["Planned", "Sterilized", "Pasteurized", "Sealed"];
    case "Colonizing":
      return ["Inoculated", "Spawned", "Colonizing"];
    case "Colonized/Fridge":
      return ["FullyColonized", "Fridge", "ColdShock"];
    case "Fruiting":
      return ["Fruiting"];
    case "Frozen":
      return ["Frozen"];
    case "Retired":
      return ["Consumed", "Retired", "Compost", "Composted", "Expired"];
    case "All Active":
      return ["Planned", "Sterilized", "Pasteurized", "Sealed", "Inoculated", "Spawned", "Colonizing", "FullyColonized", "Fridge", "ColdShock", "Fruiting", "Frozen"];
    case "All":
    default:
      return [];
  }
}

