actionConfiguration.body:
function (actionOrOptions = {}) {
  const rows = LotsPage.selectedLotRows();
  const action = typeof actionOrOptions === "string" ? actionOrOptions : null;
  const options = typeof actionOrOptions === "object" && actionOrOptions !== null ? actionOrOptions : {};
  const rulesByAction = {
    shake: {
      requireAny: true,
      allowedCategories: ["grain"],
      requireInoculated: true,
      message: "Select one or more active inoculated grain lots to shake."
    },
    retire: {
      requireAny: true,
      message: "Select one or more active lots to retire."
    },
    modify: {
      requireAny: true,
      allowedCategories: ["fruiting_block"],
      message: "Select one or more active fruiting block lots to modify."
    },
    move: {
      requireAny: true,
      requireInoculatedOrSpawned: true,
      disallowFruitingLocation: true,
      message: "Select one or more active inoculated or spawned lots that are not already in Fruiting."
    },
    package: {
      requireAny: true,
      message: "Select one or more active lots to package."
    },
    inoculate: {
      requireAny: true,
      allowedCategories: ["grain", "lc_flask", "plate"],
      requireNoStrain: true,
      requireNotInoculated: true,
      message: "Select one or more active grain, LC flask, or plate lots that have not already been inoculated or assigned a strain."
    },
    draw_syringes: {
      requireSingle: true,
      allowedCategories: ["lc_flask"],
      message: "Select exactly one active LC flask lot to draw syringes."
    },
    harvest: {
      requireSingle: true,
      allowedCategories: ["fruiting_block"],
      message: "Select exactly one active fruiting block lot to harvest."
    }
  };
  const rules = {
    ...action ? rulesByAction[action] || ({}) : {},
    ...options
  };
  if (rules.requireSingle && rows.length !== 1) {
    return {
      ok: false,
      message: rules.message || "Select exactly one valid lot."
    };
  }
  if ((rules.requireAny || !rules.requireSingle) && rows.length === 0) {
    return {
      ok: false,
      message: rules.message || "Select one or more valid lots."
    };
  }
  for (const row of rows) {
    const label = row.lot_id || row.nocopk || "Selected lot";
    const category = String(row.item_category_mat || "");
    if (rules.allowedCategories && !rules.allowedCategories.includes(category)) {
      return {
        ok: false,
        message: `${label} has category ${category || "(blank)"}; expected ${rules.allowedCategories.join(", ")}.`
      };
    }
    if (!rules.allowRetired && LotsPage.lotIsRetired(row)) {
      return {
        ok: false,
        message: `${label} is retired or unavailable (${row.status || "unknown status"}).`
      };
    }
    if (rules.requireInoculated && !row.inoculated_at) {
      return {
        ok: false,
        message: `${label} must be inoculated.`
      };
    }
    if (rules.requireInoculatedOrSpawned && !(row.inoculated_at || row.spawned_at)) {
      return {
        ok: false,
        message: `${label} must be inoculated or spawned.`
      };
    }
    if (rules.requireNoStrain && row.strain_species_strain_mat) {
      return {
        ok: false,
        message: `${label} already has a strain (${row.strain_species_strain_mat}).`
      };
    }
    if (rules.requireNotInoculated && row.inoculated_at) {
      return {
        ok: false,
        message: `${label} was already inoculated (${row.inoculated_at}).`
      };
    }
    if (rules.disallowFruitingLocation && LotsPage.lotLocationName(row).toLowerCase().includes("fruiting")) {
      return {
        ok: false,
        message: `${label} is already located in Fruiting.`
      };
    }
  }
  return {
    ok: true,
    message: ""
  };
}

