	spawnToBulkOutputPlan() {
		const text = this.spawnToBulkBlockSizesText();

		if (!text) return [];

		return text
			.split(",")
			.map(s => s.trim())
			.filter(Boolean)
			.map(token => {
				if (token.includes(":")) {
					const [item_id, size] = token.split(":").map(x => x.trim());
					return { item_id, unit_lbs: Number(size) };
				}

				return { unit_lbs: Number(token) };
			})
			.filter(x => Number.isFinite(x.unit_lbs) && x.unit_lbs > 0);
	},

