    await showModal(modalDrawSyringes.name);
  },

  async drawSyringesFromSelectedFlask() {
		if (!this.canOpenLotModal("draw_syringes")) {
			showAlert('Select exactly one active LC flask lot first.', 'warning');
			return;
		}

		const count = Number(inpSyringeCount.text);
		const mlEach = Number(inpSyringeMlEach.text);
		const mode = selDrawSyringeOutputType.selectedOptionValue || "product";
		const location = selDrawSyringeLocation.selectedOptionValue;

		if (!Number.isFinite(count) || count <= 0) {
			showAlert('Enter a syringe count greater than 0.', 'warning');
			return;
		}
		if (!Number.isFinite(mlEach) || mlEach <= 0) {
			showAlert('Enter mL per syringe greater than 0.', 'warning');
			return;
		}
		if (!location) {
			showAlert('Select a Storage Location for drawn syrings.', 'warning');
			return;
		}

		try {
			const res = mode === "product"
				? await qDrawSyringeProducts.run()
				: await qDrawSyringes.run();

			showAlert(
				mode === "product" ? 'Syringe products created.' : 'Syringe lots created.',
				'success'
			);
			closeModal(modalDrawSyringes.name);
			await LotsPage.refresh();
			return res;
		} catch (e) {
			showAlert(e?.message || String(e), 'error');
			return null;
		}
  },

	async verifyHarvestableLot() {
		return this.validateAndWarnLotModal("harvest", "Select exactly one active fruiting block lot to harvest.");
	},

	selectedHarvestItem() {
		const id = Number(selHarvestItem.selectedOptionValue);
		return (qHarvestItems.data || []).find(i => Number(i.nocopk) === id) || null;
	},

	selectedHarvestCategory() {
		return this.selectedHarvestItem()?.category || null;
	},

	harvestLocationOptions() {
		const cat = this.selectedHarvestCategory();

		return (qProductLocations.data || [])
			.filter(l => {
				const name = String(l.name || "").toLowerCase();

				if (cat === "freezer_tray") {
					return name.includes("freeze");
				}

				if (cat === "fresh_tray") {
					return name.includes("shipping") || name.includes("fulfillment");
				}

				return false;
			})
			.map(l => ({
				label: l.name,
				value: l.nocopk
			}));
	},

	async onHarvestItemChanged() {
		const opts = this.harvestLocationOptions();

		if (opts.length === 1) {
			selHarvestStorageLocation.setSelectedOption(opts[0].value);
		} else {
			selHarvestStorageLocation.setSelectedOption("");
		}
	},

	async openHarvestModal() {
		if (!this.validateAndWarnLotModal("harvest", "Select exactly one active fruiting block lot to harvest.")) return;

		txtHarvestContent.setText(this.formatSelectedLots());

		inpHarvestWeightG.setValue("");
		inpHarvestTrayCount.setValue("1");
		inpHarvestNotes.setValue("");

		await Promise.allSettled([
			qHarvestItems.run(),
			qProductLocations.run(),
			qHarvestFlushNo.run()
		]);

		const nextFlush = qHarvestFlushNo.data?.[0]?.next_flush_no || 1;
		inpHarvestFlushNo.setValue(String(nextFlush));

		await showModal(modalHarvestLot.name);
	},

	harvestFreshTrayCount() {
		return this.selectedHarvestCategory() === "fresh_tray"
			? Number(inpHarvestTrayCount.text || 0)
			: 0;
	},

	harvestFrozenTrayCount() {
		return this.selectedHarvestCategory() === "freezer_tray"
			? Number(inpHarvestTrayCount.text || 0)
			: 0;
	},

	async harvestSelectedLot() {
		if (!this.validateAndWarnLotModal("harvest", "Select exactly one active fruiting block lot to harvest.")) return;

		const weightG = Number(inpHarvestWeightG.text);
		const flushNo = Number(inpHarvestFlushNo.text);
		const trayCount = Number(inpHarvestTrayCount.text);

		if (!selHarvestItem.selectedOptionValue) {
			showAlert("Select a harvest item.", "warning");
			return;
		}

		if (!Number.isFinite(weightG) || weightG <= 0) {
			showAlert("Enter harvest weight in grams.", "warning");
			return;
		}

		if (!Number.isFinite(trayCount) || trayCount <= 0) {
			showAlert("Enter tray count.", "warning");
			return;
		}

		if (!selHarvestStorageLocation.selectedOptionValue) {
			showAlert("Select a valid harvest storage location.", "warning");
			return;
		}

		try {
			const res = await qHarvestLot.run();
			showAlert("Harvest created " + res[0].created_count + " tray product(s).", "success");
			closeModal(modalHarvestLot.name);
			await LotsPage.refresh();
			return res;
		} catch (e) {
			showAlert(e?.message || String(e), "error");
			return null;
		}
	},

	spawnToBulkTargetLotIds() {
		return this.selectedLotIds()
			.map(id => Number(id))
			.filter(Number.isFinite);
	},

	selectedSpawnBulkSourceLots() {
		return tblSpawnSourceLots.selectedRows || [];
	},

	spawnToBulkSourceLotIds() {
		return this.selectedSpawnBulkSourceLots()
			.map(r => Number(r.nocopk))
			.filter(Number.isFinite);
	},

	spawnToBulkBlockSizesText() {
		return String(inpSpawnToBulkLotsSize.text || "").trim();
	},

	spawnToBulkNotesText() {
		return String(inpSpawnToBulkNotes.text || "").trim();
	},

	spawnToBulkOutputPlan() {
		const text = this.spawnToBulkBlockSizesText();

		if (!text) return [];

		return text
			.split(",")
			.map(s => s.trim())
			.filter(Boolean)
			.map(token => {
				if (token.includes(":")) {
					const [item_id, size] = token.split(":").map(x => x.trim());
					return { item_id, unit_lbs: Number(size) };
				}

				return { unit_lbs: Number(token) };
			})
			.filter(x => Number.isFinite(x.unit_lbs) && x.unit_lbs > 0);
	},

	spawnToBulkOutputPlanJson() {
		return JSON.stringify(this.spawnToBulkOutputPlan());
	},

	spawnToBulkOutputCount() {
		const plan = this.spawnToBulkOutputPlan();
		return plan.length > 0 ? plan.length : this.spawnToBulkTargetLotIds().length;
	},

	canOpenSpawnToBulkModal() {
		return this.canOpenLotModal({
			requireAny: true,
			allowedCategories: ["substrate"],
			message: "Select one or more active substrate lots before spawning to bulk."
		});
	},

	async openSpawnToBulkModal() {
		if (!this.validateAndWarnLotModal({
			requireAny: true,
			allowedCategories: ["substrate"],
			message: "Select one or more active substrate lots before spawning to bulk."
		})) return;

		txtSpawnToBulkContent.setText(this.formatSelectedLots());
		inpSpawnToBulkNotes.setValue("");
		inpSpawnToBulkLotsSize.setValue("");

		await qSpawnSourceLotsSearch.run();
		await showModal(modalSpawnToBulk.name);
	},

	canSubmitSpawnToBulk() {
		const targets = tblLots.selectedRows || [];
		const sources = this.selectedSpawnBulkSourceLots();

		if (!this.canOpenSpawnToBulkModal()) return false;
		if (sources.length < 1) return false;

		if (!sources.every(r => r.item_category_mat === "grain")) return false;

		const sourceSpecies = [
			...new Set(sources.map(r =>
				String(r.strain_species || r.strain_species_strain_mat || "").trim()
			))
		].filter(Boolean);

		return sourceSpecies.length === 1;
	},

	async submitSpawnToBulk() {
		if (!this.canSubmitSpawnToBulk()) {
			showAlert("Select active substrate targets and one or more colonized grain source lots of the same species.", "warning");
			return;
		}

		try {
			const res = await qSpawnToBulkLots.run();
			const created = res?.[0]?.created_count ?? 0;

			showAlert(`Spawn to Bulk complete. Created ${created} fruiting block lot(s).`, "success");
			closeModal(modalSpawnToBulk.name);
			await this.refresh();
			return res;
		} catch (e) {
			showAlert(e?.message || String(e), "error");
			return null;
		}
	},

};

