export default {
  currentOperator() {
    const email = (appsmith.user?.email || "").trim().toLowerCase();
    const name = (appsmith.user?.name || "").trim();
    if (email) return email;
    if (name) return name;
    return "system";
  },

  sql: {
    str(v) {
      if (v === undefined || v === null || v === "") return "NULL";
      return "'" + String(v).replace(/'/g, "''") + "'";
    },
    num(v) {
      const n = Number(v);
      return Number.isFinite(n) ? String(n) : "NULL";
    },
    arrBigint(arr) {
      if (!arr || arr.length === 0) return "ARRAY[]::bigint[]";
      const vals = arr.map(x => {
        const n = Number(x);
        return Number.isFinite(n) ? String(n) : "NULL";
      }).filter(x => x !== "NULL");
      if (vals.length === 0) return "ARRAY[]::bigint[]";
      return "ARRAY[" + vals.join(", ") + "]::bigint[]";
    },
  },

  selectedProductIds() {
    return (tblProducts.selectedRows || []).map(r => r.nocopk).filter(Boolean);
  },

  selectedTrayProducts() {
    return (tblProducts.selectedRows || []).filter(r => ["fresh_tray", "freezer_tray"].includes(String(r.item_category_mat || "")));
  },

  selectedFreezerTrayProducts() {
    return (tblProducts.selectedRows || []).filter(r => String(r.item_category_mat || "") === "freezer_tray");
  },

  selectedProductsSummary() {
    const rows = tblProducts.selectedRows || [];
    if (!rows.length) return "No products selected.";
    return rows.map(r => `${r.product_id || r.nocopk} — ${r.name || r.item_category_mat || "Product"} — ${r.storage_location || "No location"}`).join("\n");
  },

  async refresh() {
    await qProducts_del.run();
  },

  async showFreshTrays() {
    await selProductsCategory.setSelectedOption("fresh_tray");
    await this.refresh();
  },

  async showFreezerTrays() {
    await selProductsCategory.setSelectedOption("freezer_tray");
    await this.refresh();
  },

  canMoveFreezeDryer() {
    const rows = tblProducts.selectedRows || [];
    return rows.length > 0 && rows.every(r => String(r.item_category_mat || "") === "freezer_tray" && !["consumed", "retired", "spoiled", "compost"].includes(String(r.tray_state || "").toLowerCase()));
  },

  canRetireTray() {
    const rows = tblProducts.selectedRows || [];
    return rows.length > 0 && rows.every(r => ["fresh_tray", "freezer_tray"].includes(String(r.item_category_mat || "")) && !["consumed", "retired", "spoiled", "compost"].includes(String(r.tray_state || "").toLowerCase()));
  },

  async openMoveFreezeDryerModal() {
    if (!this.canMoveFreezeDryer()) {
      showAlert("Select one or more active freezer tray products.", "warning");
      return;
    }
    inpMoveFreezeDryerNotes.setValue("");
    const opts = this.freezeDryerLocationOptions();
    if (opts.length === 1) {
      selFreezeDryerLocation.setSelectedOption(opts[0].value);
    }
    await showModal(modalMoveFreezeDryer.name);
  },

  async openRetireTrayModal() {
    if (!this.canRetireTray()) {
      showAlert("Select one or more active fresh/freezer tray products.", "warning");
      return;
    }
    selRetireTrayReason.setSelectedOption("");
    inpRetireTrayNotes.setValue("");
    await showModal(modalRetireTray.name);
  },

  freezeDryerLocationOptions() {
    return (qProductLocationOptions_del.data || [])
      .filter(l => String(l.name || "").toLowerCase().includes("freeze dryer"))
      .map(l => ({ label: l.name, value: l.nocopk }));
  },

  canSubmitMoveFreezeDryer() {
    return this.canMoveFreezeDryer() && !!selFreezeDryerLocation.selectedOptionValue;
  },

  canSubmitRetireTray() {
    return this.canRetireTray() && !!selRetireTrayReason.selectedOptionValue;
  },

  async moveToFreezeDryer() {
    if (!this.canSubmitMoveFreezeDryer()) {
      showAlert("Select active freezer tray products and a Freeze Dryer location.", "warning");
      return;
    }
    const res = await qMoveProductsToFreezeDryer.run();
    showAlert("Moved freezer tray product(s) to Freeze Dryer.", "success");
    closeModal(modalMoveFreezeDryer.name);
    await this.refresh();
    return res;
  },

  async retireTrayProducts() {
    if (!this.canSubmitRetireTray()) {
      showAlert("Select active tray products and a reason.", "warning");
      return;
    }
    const res = await qRetireTrayProducts.run();
    showAlert("Tray product(s) updated.", "success");
    closeModal(modalRetireTray.name);
    await this.refresh();
    return res;
  },

  canSubmitPackageFreezeDried() {
    const count = Number(inpPkgFDCount.text);
    const sizeG = Number(inpPkgFDSizeG.text);
    const rows = tblProducts.selectedRows || [];
    return rows.length > 0
      && rows.every(r => String(r.item_category_mat || "") === "freezer_tray")
      && Number.isFinite(count) && count > 0
      && Number.isFinite(sizeG) && sizeG > 0
      && !!selPkgFDLocation.selectedOptionValue
      && !!dpPkgFDUseBy.formattedDate;
  },

  async packageFreezeDried() {
    if (!this.canSubmitPackageFreezeDried()) {
      showAlert("Select freezer tray products and complete the package form.", "warning");
      return;
    }
    const res = await qPackageFreezeDried.run();
    showAlert("Packaged freeze dried product(s) created.", "success");
    closeModal(modalPackageFreezeDried.name);
    await this.refresh();
    return res;
  },
};

